                            st.append((c, d))
    return n

def solve(t):
    st = []
    for x in t:
        if x in ('+', '-', '*', '/'):
            b = st.pop()
            a = st.pop()
            if x == '+':
                st.append(a + b)
            elif x == '-':
                st.append(a - b)
            elif x == '*':
                st.append(a * b)
            else:
                q = abs(a) // abs(b)
                st.append(q if (a < 0) == (b < 0) else -q)
        else:
            st.append(int(x))
    return st[0]

