def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest ending value of an inc subseq of length i+1
    for x in nums:
        # find index where x can extend
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

