    """Evaluate Reverse Polish Notation with integer division truncating toward zero.
    Uses only integer arithmetic to avoid float precision issues.
    """
    stack = []
    for token in tokens:
        if token not in {'+', '-', '*', '/'}:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division truncates toward zero
                # Perform division using absolute values to avoid float
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = sign * (abs(a) // abs(b))
            stack.append(res)
    return stack[0] if stack else 0
