def solve(s):
    """Convert a Roman numeral to integer.
    Handles uppercase or lowercase input, and ignores surrounding whitespace.
    """
    if not s:
        return 0
    s = s.strip().upper()
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        # Look ahead for subtractive pair
        if i + 1 < n and values.get(s[i], 0) < values.get(s[i+1], 0):
            total += values[s[i+1]] - values[s[i]]
            i += 2
        else:
            total += values.get(s[i], 0)
            i += 1
    return total

